//! In-memory SCIP index loader and query engine for benchmark comparisons.
//! Parses `index.scip` generated by `rust-analyzer scip` and provides O(1) def/refs/hover.

use protobuf::Message;
use scip::types::{Index, SymbolRole};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::Instant;

use super::types::{ExternalLspResult, ServerMetrics, SymmetricScenario};

#[derive(Debug, Clone)]
pub struct ScipLocation {
    pub file: String,
    pub line: u32,
    pub col: u32,
}

pub type LineOccurrence = (u32, u32, String);
pub type OccurrenceMap = HashMap<(String, u32), Vec<LineOccurrence>>;

#[derive(Default)]
pub struct ScipIndex {
    pub workspace_root: PathBuf,
    // (norm_file, line) -> Vec<(start_col, end_col, symbol)>
    pub occurrences_by_line: OccurrenceMap,
    // symbol -> definition location
    pub definitions: HashMap<String, ScipLocation>,
    // symbol -> all reference locations
    pub references: HashMap<String, Vec<ScipLocation>>,
    // symbol -> documentation string
    pub docs: HashMap<String, String>,
    pub load_time_micros: u128,
}

impl ScipIndex {
    pub fn load_from_file(scip_path: &Path, workspace_root: &Path) -> Result<Self, String> {
        let t_start = Instant::now();
        let bytes = std::fs::read(scip_path)
            .map_err(|e| format!("Failed to read SCIP index {}: {}", scip_path.display(), e))?;

        let index = Index::parse_from_bytes(&bytes)
            .map_err(|e| format!("Failed to parse protobuf SCIP index: {}", e))?;

        let mut occurrences_by_line: OccurrenceMap = HashMap::new();
        let mut definitions = HashMap::new();
        let mut references: HashMap<String, Vec<ScipLocation>> = HashMap::new();
        let mut docs = HashMap::new();

        for doc in index.documents {
            let rel_path = doc.relative_path.clone();

            for sym_info in doc.symbols {
                if !sym_info.documentation.is_empty() {
                    docs.insert(sym_info.symbol.clone(), sym_info.documentation.join("\n"));
                }
            }

            for occ in doc.occurrences {
                if occ.range.len() < 3 {
                    continue;
                }
                let line = occ.range[0] as u32;
                let start_col = occ.range[1] as u32;
                let end_col = occ.range[2] as u32;
                let symbol = occ.symbol.clone();

                let is_def = (occ.symbol_roles & (SymbolRole::Definition as i32)) != 0;
                let loc = ScipLocation {
                    file: rel_path.clone(),
                    line,
                    col: start_col,
                };

                if is_def {
                    definitions.insert(symbol.clone(), loc.clone());
                } else {
                    references
                        .entry(symbol.clone())
                        .or_default()
                        .push(loc.clone());
                }

                occurrences_by_line
                    .entry((rel_path.clone(), line))
                    .or_default()
                    .push((start_col, end_col, symbol));
            }
        }

        let load_time_micros = t_start.elapsed().as_micros();

        Ok(Self {
            workspace_root: workspace_root.to_path_buf(),
            occurrences_by_line,
            definitions,
            references,
            docs,
            load_time_micros,
        })
    }

    pub fn find_symbol_at(&self, rel_file: &str, line: u32, col: u32) -> Option<&str> {
        let occs = self
            .occurrences_by_line
            .get(&(rel_file.to_string(), line))?;
        for (start_c, end_c, sym) in occs {
            if col >= *start_c && col <= *end_c {
                return Some(sym.as_str());
            }
        }
        occs.first().map(|(_, _, sym)| sym.as_str())
    }

    pub fn goto_definition(&self, rel_file: &str, line: u32, col: u32) -> Option<ScipLocation> {
        let sym = self.find_symbol_at(rel_file, line, col)?;
        self.definitions.get(sym).cloned()
    }

    pub fn find_references(&self, rel_file: &str, line: u32, col: u32) -> Vec<ScipLocation> {
        let sym = match self.find_symbol_at(rel_file, line, col) {
            Some(s) => s,
            None => return Vec::new(),
        };
        let mut all = Vec::new();
        if let Some(def_loc) = self.definitions.get(sym) {
            all.push(def_loc.clone());
        }
        if let Some(refs) = self.references.get(sym) {
            all.extend(refs.clone());
        }
        all
    }

    pub fn hover(&self, rel_file: &str, line: u32, col: u32) -> Option<String> {
        let sym = self.find_symbol_at(rel_file, line, col)?;
        self.docs.get(sym).cloned()
    }
}

pub fn run_scip_session(
    scip_path: &Path,
    workspace_root: &Path,
    scenarios: &[SymmetricScenario],
) -> Option<ServerMetrics> {
    let scip_index = ScipIndex::load_from_file(scip_path, workspace_root).ok()?;
    let readiness_warmup_micros = scip_index.load_time_micros;

    let mut query_latencies_micros = HashMap::new();
    let mut query_cold_latencies_micros = HashMap::new();
    let mut query_results = HashMap::new();

    for sc in scenarios {
        let (file, line, col) = match &sc.location {
            Some((f, l, c)) => {
                let p = Path::new(f);
                let rel = if let Ok(stripped) = p.strip_prefix(workspace_root) {
                    stripped.display().to_string()
                } else {
                    f.clone()
                };
                (rel, l.saturating_sub(1), c.saturating_sub(1))
            }
            None => continue,
        };

        let mut iteration_latencies = Vec::with_capacity(3);
        let mut last_res = ExternalLspResult {
            found: false,
            span: "Not found".to_string(),
            count: 0,
            latency_micros: 0,
            rss_bytes: 0,
        };

        for iter in 0..3 {
            let t_start = Instant::now();
            let res = match sc.capability.as_str() {
                "def" | "textDocument/definition" => {
                    if let Some(loc) = scip_index.goto_definition(&file, line, col) {
                        let full_path = workspace_root.join(&loc.file);
                        ExternalLspResult {
                            found: true,
                            span: format!(
                                "{}:{}:{}",
                                full_path.display(),
                                loc.line + 1,
                                loc.col + 1
                            ),
                            count: 1,
                            latency_micros: 0,
                            rss_bytes: 0,
                        }
                    } else {
                        ExternalLspResult {
                            found: false,
                            span: "Not found".to_string(),
                            count: 0,
                            latency_micros: 0,
                            rss_bytes: 0,
                        }
                    }
                }
                "refs" | "textDocument/references" => {
                    let refs = scip_index.find_references(&file, line, col);
                    let count = refs.len();
                    ExternalLspResult {
                        found: count > 0,
                        span: refs
                            .first()
                            .map(|loc| {
                                format!(
                                    "{}:{}:{}",
                                    workspace_root.join(&loc.file).display(),
                                    loc.line + 1,
                                    loc.col + 1
                                )
                            })
                            .unwrap_or_else(|| "Not found".to_string()),
                        count,
                        latency_micros: 0,
                        rss_bytes: 0,
                    }
                }
                "hover" | "textDocument/hover" => {
                    let doc = scip_index.hover(&file, line, col);
                    ExternalLspResult {
                        found: doc.is_some(),
                        span: doc.unwrap_or_else(|| "N/A".to_string()),
                        count: 1,
                        latency_micros: 0,
                        rss_bytes: 0,
                    }
                }
                _ => ExternalLspResult {
                    found: false,
                    span: "N/A".to_string(),
                    count: 0,
                    latency_micros: 0,
                    rss_bytes: 0,
                },
            };
            let lat = t_start.elapsed().as_micros();
            iteration_latencies.push(lat);
            if iter == 0 {
                last_res = res;
            }
        }

        let cold_lat = iteration_latencies[0];
        let warm_lat = if iteration_latencies.len() > 1 {
            let mut sorted = iteration_latencies[1..].to_vec();
            sorted.sort_unstable();
            sorted[sorted.len() / 2]
        } else {
            cold_lat
        };

        last_res.latency_micros = warm_lat;
        query_cold_latencies_micros.insert(sc.name.clone(), cold_lat);
        query_latencies_micros.insert(sc.name.clone(), warm_lat);
        query_results.insert(sc.name.clone(), last_res);
    }

    Some(ServerMetrics {
        server_name: "rust-analyzer-scip".to_string(),
        server_version: "1.98.1".to_string(),
        spawn_and_init_micros: 0,
        readiness_warmup_micros,
        query_latencies_micros,
        query_cold_latencies_micros,
        query_results,
        shutdown_micros: 0,
        peak_rss_bytes: super::system::get_current_process_rss_bytes(),
        peak_rss_anon_bytes: super::system::get_current_process_rss_bytes(),
        peak_rss_file_bytes: 0,
        cargo_spawned: false,
        peak_open_fds: super::system::get_process_fd_count(std::process::id()),
        peak_threads: super::system::get_process_thread_count(std::process::id()),
        peak_ridx_open_fds: 0,
        peak_ridx_mapped_regions: 0,
    })
}
